// EDITAR UNA VEZ tras importar: valores del despliegue que NO son secretos.
// Las claves privadas (GitHub, Claude, clave de servicio de Supabase, Gmail) van en credenciales de n8n, nunca aquí.
return [{ json: {
  github_repo: 'TU-USUARIO/meridiano-motor',                    // repositorio donde corre el motor (GitHub Actions)
  github_rama: 'main',
  supabase_url: 'https://xxxxxxxx.supabase.co',
  hoja_datos_id: 'ID-de-la-hoja-de-Google-Sheets',               // lo que va entre /d/ y /edit en la URL de la hoja
  panel_url: 'https://meridiano-panel.lovable.app',
  correo_direccion: 'direccion@meridiano.com',
  correo_datos: 'datos@meridiano.com',                           // responsable de la hoja de datos (avisos de la carga)
  modelo_ia: 'claude-sonnet-5-5',
  // MODO DEMO (datos ficticios): todos los correos van al buzón de pruebas, con el destinatario real en el asunto.
  // Los correos salen de la cuenta de Gmail conectada en n8n; el buzón de pruebas puede ser esa misma cuenta (con alias +demo).
  modo_demo: true,
  buzon_demo: 'TU-CUENTA+demo@gmail.com',
} }];

// ¿Qué hay que enviar?
//  · Webhook de Supabase (evento nuevo): solo la propuesta de ese evento, y solo si el evento es una aceptación.
//    Así dos aceptaciones seguidas no se envían dos veces.
//  · Lanzamiento a mano («Reintentar envíos pendientes»): todas las aceptadas que sigan sin enviar.
const wh = $('Propuesta aceptada en el panel');
if (wh.isExecuted) {
  return wh.all()
    .map(i => i.json.body || i.json)
    .filter(b => b.table === 'eventos_propuesta' && b.type === 'INSERT' && b.record && b.record.accion === 'aprobar')
    .map(b => ({ json: { filtro: `&id=eq.${Number(b.record.propuesta_id)}` } }));
}
return [{ json: { filtro: '' } }];

// Un correo por propuesta aceptada, con el TEXTO APROBADO (el que quedó congelado al pulsar «Aceptar»).
// Seguridad: un contacto ficticio nunca recibe correo fuera del modo demo.
const cfg = $('Configuración').first().json;
const filas = $input.all().map(i => i.json).filter(p => p && p.id);
return filas.map(p => {
  const bloqueo = (!cfg.modo_demo && p.contacto_ficticio) ? 'Contacto ficticio: no se envía fuera del modo demo' : null;
  const aviso = cfg.modo_demo ? `[Correo de demostración. En real iría a ${p.contacto_nombre} <${p.contacto_email}>]\n\n` : '';
  return { json: {
    id: p.id, razon_social: p.razon_social, bloqueo,
    para: p.contacto_email,
    asunto: p.asunto_email || p.material_titulo || `Meridiano · ${p.razon_social}`,
    texto: aviso + p.texto_aprobado + `\n\n${p.comercial_nombre}\nMeridiano · Departamento comercial`,
  } };
});

// Resultado de cada envío de Gmail → registrar_envio en Supabase (enviada con su id de mensaje, o error_envio con el motivo).
const enviados = $('Solo enviables').all().map(i => i.json);
const bloqueados = $('Preparar correo').all().map(i => i.json).filter(p => p.bloqueo);
const res = $input.all().map(i => i.json || {});
const out = enviados.map((p, k) => {
  const r = res[k] || {};
  const ok = !!(r.id || r.threadId) && !r.error;
  const error = ok ? null : String((r.error && (r.error.message || r.error.description)) || r.error || 'Gmail no ha confirmado el envío').slice(0, 400);
  return { json: { p_propuesta_id: p.id, p_accion: 'registrar_envio', p_usuario: 'n8n',
                   p_datos: ok ? { ok: true, id_mensaje: r.id } : { ok: false, error } } };
});
for (const p of bloqueados)
  out.push({ json: { p_propuesta_id: p.id, p_accion: 'registrar_envio', p_usuario: 'n8n', p_datos: { ok: false, error: p.bloqueo } } });
return out;
